MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  ColormapType
    colormap[256];

  ExceptionInfo
    *exception;

  int
    y;

  register int
    x;

  register PixelIndex
    *p;

  size_t
    count,
    number_colors;

  ssize_t
    count_;

  unsigned char
    *indexes;

  /* Initialize exception */
  exception = &image->exception;

  /* Validate input */
  if (image->colors > 256)
    {
      (void) ThrowMagickException(exception, GetMagickModule(), ImageError,
        "ImageColorCountExceedsLimit","`%s'", image->filename);
      return (MagickFalse);
    }

  number_colors = image->colors;

  /* Allocate memory for colormap and pixel indexes */
  indexes = (unsigned char *) AcquireMemory(number_colors * image->columns *
    sizeof(*indexes));
  if (indexes == (unsigned char *) NULL)
    {
      (void) ThrowMagickException(exception, GetMagickModule(),
        ResourceLimitError, "UnableToAllocateMemory", "%s", image->filename);
      return (MagickFalse);
    }

  /* Transform image to sRGB colorspace if needed */
  if (image->colorspace != sRGBColorspace)
    (void) TransformImageColorspace(image, sRGBColorspace, exception);

  /* Build colormap */
  for (y = 0; y < (int) number_colors; y++)
  {
    colormap[y].red = (unsigned short) (QuantumScale * image->colormap[y].red + 0.5);
    colormap[y].green = (unsigned short) (QuantumScale * image->colormap[y].green + 0.5);
    colormap[y].blue = (unsigned short) (QuantumScale * image->colormap[y].blue + 0.5);
  }

  /* Write colormap */
  count = 0;
  for (y = 0; y < (int) number_colors; y++)
  {
    for (x = 0; x < 3; x++)
    {
      unsigned char
        byte;

      if (x == 0)
        byte = (unsigned char) colormap[y].red;
      else if (x == 1)
        byte = (unsigned char) colormap[y].green;
      else
        byte = (unsigned char) colormap[y].blue;
      count_ = (ssize_t) fwrite(&byte, 1, 1, image->file);
      if (count_ != 1)
        break;
    }
    if (count_ != 1)
      break;
    count++;
  }

  if (count != number_colors)
  {
    (void) fclose(image->file);
    image->file = (FILE *) NULL;
    return (MagickFalse);
  }

  /* Write pixel indexes */
  p = GetPixelIndexes(image);
  count = 0;
  for (y = 0; y < (int) image->rows; y++)
  {
    count_ = (ssize_t) fwrite(p, sizeof(*p), image->columns, image->file);
    if (count_ != (ssize_t) image->columns)
      break;
    count++;
  }

  if (count != (size_t) image->rows)
  {
    (void) fclose(image->file);
    image->file = (FILE *) NULL;
    return (MagickFalse);
  }

  /* Clean up */
  indexes = (unsigned char *) RelinquishMemory(indexes);

  return (MagickTrue);
}

