MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  ColormapType
    colormap;

  ExceptionInfo
    *exception;

  MagickBooleanType
    status;

  register ssize_t
    i;

  size_t
    colormap_size;

  StringInfo
    *profile;

  unsigned char
    *pixels;

  /* Validate input */
  assert(image_info != (ImageInfo *) NULL);
  assert(image != (Image *) NULL);
  assert(image->signature == MagickSignature);

  exception = &(GetImageException(image));

  if (image->colors > 256)
    {
      ThrowMagickException(exception, GetMagickModule(), ImageError,
        "MAPFormatSupportsOnly256Colors", " MAP format supports only 256 colors");
      return (MagickFalse);
    }

  colormap_size = 256 * sizeof(ColormapType);
  colormap = (ColormapType *) AcquireMemory(colormap_size);
  if (colormap == (ColormapType *) NULL)
    {
      ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
        "MemoryAllocationFailed", " Unable to allocate memory for colormap");
      return (MagickFalse);
    }

  for (i = 0; i < (ssize_t) image->colors; i++)
  {
    colormap[i] = image->colormap[i];
  }

  pixels = (unsigned char *) AcquireMemory(image->columns * image->rows);
  if (pixels == (unsigned char *) NULL)
  {
    RelinquishMemory(colormap);
    ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
      "MemoryAllocationFailed", " Unable to allocate memory for pixels");
    return (MagickFalse);
  }

  status = WriteBlobFile(image, 256 * sizeof(ColormapType), 1, colormap);
  if (!status)
  {
    RelinquishMemory(colormap);
    RelinquishMemory(pixels);
    return (MagickFalse);
  }

  for (i = 0; i < (ssize_t) image->rows; i++)
    for (size_t j = 0; j < image->columns; j++)
      pixels[i * image->columns + j] = (unsigned char) GetPixelIndex(image, &image->pixels[i][j]);

  status = WriteBlobFile(image, image->columns * image->rows, 1, pixels);

  RelinquishMemory(colormap);
  RelinquishMemory(pixels);

  return (status ? MagickTrue : MagickFalse);
}

