MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  MagickBooleanType status;
  FILE
    *file;

  MagickPixelPacket
    *colormap;

  size_t
    colormap_size;

  unsigned char
    *pixels;

  if (image == (Image *) NULL)
    return(MagickFalse);

  file = fopen(image_info->filename, "wb");
  if (file == (FILE *) NULL)
    return(MagickFalse);

  (void) TransformImageColorspace(image, sRGBColorspace);

  colormap_size = image->number_unique_colors;
  if (colormap_size > 256)
    colormap_size = 256;

  colormap = (MagickPixelPacket *) AcquireMemory(colormap_size *
    sizeof(*colormap));
  if (colormap == (MagickPixelPacket *) NULL)
    {
      fclose(file);
      ThrowException(&image->exception, ResourceLimitError,
        "MemoryAllocationFailed", image_info->filename);
      return(MagickFalse);
    }

  GetImageColormap(image, colormap, colormap_size);

  if (fwrite(colormap, sizeof(*colormap), colormap_size, file) !=
       colormap_size)
    {
      fclose(file);
      RelinquishMemory(colormap);
      return(MagickFalse);
    }

  pixels = (unsigned char *) AcquireMemory(image->columns * image->rows *
    sizeof(*pixels));
  if (pixels == (unsigned char *) NULL)
    {
      fclose(file);
      RelinquishMemory(colormap);
      ThrowException(&image->exception, ResourceLimitError,
        "MemoryAllocationFailed", image_info->filename);
      return(MagickFalse);
    }

  GetImagePixelIndexes(image, pixels);

  if (fwrite(pixels, sizeof(*pixels), image->columns * image->rows, file) !=
       image->columns * image->rows)
    {
      fclose(file);
      RelinquishMemory(colormap);
      RelinquishMemory(pixels);
      return(MagickFalse);
    }

  RelinquishMemory(colormap);
  RelinquishMemory(pixels);
  fclose(file);

  return(MagickTrue);
}
